from __future__ import absolute_import

from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass

logger = BackgroundLogger.Instance()


class Accounts(BaseClass):
    """
    Accounts
    """

    def __init__(self):
        super(Accounts, self).__init__()

    def update_local_user_account(self, **kwargs):
        username = kwargs["username"]
        password = kwargs.get("password", None)
        new_username = kwargs.get("new_username", None)
        new_password = kwargs.get("new_password", None)
        active_status = kwargs.get("active_status", None)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.update_local_user_account(username, password=password, new_username=new_username,
                                                             new_password=new_password, connection=connection, active_status=active_status)

    def refresh_token(self, **kwargs):
        username = kwargs["username"]
        password = kwargs["password"]
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.refresh_token(username, password, connection=connection)

    def update_service_account_password(self, **kwargs):
        username = kwargs["username"]
        password = kwargs["password"]
        new_password = kwargs["new_password"]
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.update_service_account_password(username, password, new_password,
                                                                   connection=connection)

    def get_cu_operation_history(self, **kwargs):
        timeout = kwargs.get('timeout', 30)
        connection = kwargs.get("alias", "default")
        return self.factory.cu_oam.get_cu_operation_history(timeout=timeout, connection=connection)

    def get_sessions_list(self, **kwargs):
        timeout = kwargs.get('timeout', 30)
        connection = kwargs.get("alias", "default")
        return self.factory.cu_oam.get_sessions_list(timeout=timeout, connection=connection)

